// Generate CSP-compatible validation from the pinned, maintained JSON Resume schema.
import { writeFile } from 'node:fs/promises';
import Ajv from 'ajv';
import addFormats from 'ajv-formats';
import standalone from 'ajv/dist/standalone/index.js';
import schema from '@jsonresume/schema/schema.json' with { type: 'json' };
const ajv = new Ajv({ strict: false, code: { source: true } });
addFormats(ajv);
const validate = ajv.compile(schema);
await writeFile(
  'src/services/interoperability/generated/json-resume.cjs',
  '// Generated by scripts/generate-validator.mjs. Do not edit.\n' +
    standalone(ajv, validate),
);
